fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Determine how many participants to consider, at most n or length of participations
    let limit = n.min(participations.len() as u8) as usize;

    // Count how many participants are eligible:
    // eligible means (5 - attendance_count) >= k
    let eligible_count = participations
        .iter()
        .take(limit)
        .filter(|&&attendance| 5u8.saturating_sub(attendance) >= k)
        .count();

    // Each team requires exactly 3 eligible participants
    (eligible_count / 3) as u8
}